    private static partial void plImGui_CalcTextSize(byte* text, byte* text_end, [MarshalAs(UnmanagedType.U1)] bool hide_text_after_double_hash, float wrap_width, Vec2* out_result);

    public static Vec2 CalcTextSize(ReadOnlySpan<byte> text, ReadOnlySpan<byte> text_end = default, bool hide_text_after_double_hash = false, float wrap_width = -1.0f)
    {
        Vec2 result = default;
        fixed (byte* p_text = text)
        fixed (byte* p_text_end = text_end)
        {
            plImGui_CalcTextSize(p_text, p_text_end, hide_text_after_double_hash, wrap_width, &result);
        }
        return result;
    }

    public static Vec2 CalcTextSize(string text, string? text_end = null, bool hide_text_after_double_hash = false, float wrap_width = -1.0f)
    {
        Span<byte> s_text = stackalloc byte[StackTextBytes];
        byte[]? r_text = null;
        Span<byte> e_text = Encode(text, s_text, ref r_text);
        Span<byte> s_text_end = stackalloc byte[StackTextBytes];
        byte[]? r_text_end = null;
        Span<byte> e_text_end = Encode(text_end, s_text_end, ref r_text_end);
        Vec2 result = CalcTextSize(e_text, e_text_end, hide_text_after_double_hash, wrap_width);
        Return(r_text);
        Return(r_text_end);
        return result;
    }

