    private static Span<byte> Encode(string? value, Span<byte> scratch, ref byte[]? rented)
    {
        if (string.IsNullOrEmpty(value))
        {
            return Span<byte>.Empty;
        }

        int maximum = Encoding.UTF8.GetMaxByteCount(value.Length) + 1;
        Span<byte> destination = scratch;
        if (maximum > scratch.Length)
        {
            rented = System.Buffers.ArrayPool<byte>.Shared.Rent(maximum);
            destination = rented;
        }

        int written = Encoding.UTF8.GetBytes(value, destination);
        destination[written] = 0;
        return destination[..(written + 1)];
    }

    private static void Return(byte[]? rented)
    {
        if (rented is not null)
        {
            System.Buffers.ArrayPool<byte>.Shared.Return(rented);
        }
    }
